package at.andrew.squashtap;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round-xhdpi") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ScorePaletteUiTest {
 private ActivityController<MainActivity> controller;private MainActivity a;private SharedPreferences p;
 @Before public void setup(){p=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchState m=new MatchState("palette-ui",3);m.serving(1,-1);MatchBook b=new MatchBook(m);b.add(0);b.add(1);p.edit().clear().putString("match_book",b.encode()).putString(MatchDisplayPolicy.ACTIVE_MATCH,m.id()).putBoolean("asked_match_notification",true).commit();controller=Robolectric.buildActivity(MainActivity.class).setup();a=controller.get();a.action(TouchTargets.MENU);click("Settings");}
 @After public void done(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();controller.pause().stop().destroy();}
 private Button find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 private void click(String label){Button b=find(ShadowDialog.getLatestDialog().getWindow().getDecorView(),label);assertNotNull(label,b);b.performClick();}
 private Bitmap render(ScoreView v){int s=466;v.measure(View.MeasureSpec.makeMeasureSpec(s,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(s,View.MeasureSpec.EXACTLY));v.layout(0,0,s,s);Bitmap b=Bitmap.createBitmap(s,s,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));return b;}
 @Test public void choosingFromListPersistsWithoutChangingTheMatchAndCancelKeepsIt(){String before=p.getString("match_book","");click("Colour scheme: Classic");click("Neon Lime");assertEquals("neon-lime",p.getString("score_palette",""));assertEquals(before,p.getString("match_book",""));assertEquals("palette-ui",p.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));assertNotNull(find(ShadowDialog.getLatestDialog().getWindow().getDecorView(),"✓ Neon Lime"));click("Back to Settings");click("Colour scheme: Neon Lime");click("Back to Settings");assertEquals("neon-lime",p.getString("score_palette",""));}
 @Test public void allSchemesRenderBothScoresAndKeepAmbientMonochrome()throws Exception{ScoreView v=ReflectionHelpers.getField(a,"counter");File dir=new File("build/qa/palettes");dir.mkdirs();for(String id:ScorePalette.IDS){v.palette(id);Bitmap b=render(v);ScorePalette pal=ScorePalette.get(id);assertEquals(pal.left,b.getPixel(60,200));assertEquals(pal.right,b.getPixel(400,200));try(FileOutputStream o=new FileOutputStream(new File(dir,id+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}v.ambient(true,false);Bitmap ambient=render(v);assertEquals(Color.BLACK,ambient.getPixel(90,145));for(int y=0;y<466;y+=7)for(int x=0;x<466;x+=7){int c=ambient.getPixel(x,y);assertEquals(Color.red(c),Color.green(c));assertEquals(Color.red(c),Color.blue(c));}v.ambient(false,false);}}
 @Test public void brightnessHelpLeavesSystemBrightnessInControl(){assertEquals(-1f,a.getWindow().getAttributes().screenBrightness,0);click("Brightness: watch system");assertEquals(-1f,ShadowDialog.getLatestDialog().getWindow().getAttributes().screenBrightness,0);click("Open watch display settings");Intent intent=org.robolectric.Shadows.shadowOf(a).getNextStartedActivity();assertNotNull(intent);assertEquals(android.provider.Settings.ACTION_DISPLAY_SETTINGS,intent.getAction());assertEquals(-1f,a.getWindow().getAttributes().screenBrightness,0);}
}
